insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), 'jean-luc-melenchon', 'Jean-Luc Mélenchon', '/candidates/jean-luc-melenchon.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:lfi'), 'Né le 19 août 1951 à Tanger, Jean-Luc Mélenchon est ancien sénateur (1986-2009) et ministre de l''Enseignement professionnel (2000-2002). Fondateur de La France insoumise en 2016, il a été candidat à la présidentielle en 2012, 2017 et 2022 et député des Bouches-du-Rhône de 2017 à 2022.', 'https://melenchon2027.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 1) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), 'francois-ruffin', 'François Ruffin', '/candidates/francois-ruffin.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:debout'), 'Né le 18 octobre 1975 à Calais, François Ruffin est journaliste, fondateur du journal Fakir en 1999 et réalisateur du documentaire « Merci patron ! » (2016). Député de la Somme depuis 2017, il a quitté La France insoumise en 2024 et préside le mouvement Debout ! depuis juin 2025.', 'https://francoisruffin.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 2) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), 'marine-tondelier', 'Marine Tondelier', '/candidates/marine-tondelier.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:ecologistes'), 'Née le 23 août 1986 à Bois-Bernard, Marine Tondelier est diplômée de Sciences Po Lille. Élue régionale des Hauts-de-France depuis 2021, elle est secrétaire nationale des Écologistes depuis décembre 2022, réélue à ce poste avec 90,8 % des voix.', 'https://marinetondelier.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 3) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), 'raphael-glucksmann', 'Raphaël Glucksmann', '/candidates/raphael-glucksmann.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:place-publique'), 'Né le 15 octobre 1979 à Boulogne-Billancourt, Raphaël Glucksmann est journaliste et documentariste de formation. Cofondateur du parti Place publique en 2018, il est député européen depuis juillet 2019 et co-président du mouvement depuis décembre 2022.', 'https://glucks2027.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 4) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), 'gabriel-attal', 'Gabriel Attal', '/candidates/gabriel-attal.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:renaissance'), 'Né le 16 mars 1989 à Clamart, Gabriel Attal a occupé plusieurs postes ministériels avant de devenir Premier ministre de janvier à septembre 2024, plus jeune chef de gouvernement de la Ve République. Il est secrétaire général du parti Renaissance depuis décembre 2024 et préside le groupe Ensemble pour la République à l''Assemblée nationale.', 'https://attalpresident.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 5) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), 'edouard-philippe', 'Édouard Philippe', '/candidates/edouard-philippe.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:horizons'), 'Né le 28 novembre 1970 à Rouen, Édouard Philippe est diplômé de Sciences Po et de l''ENA. Maire du Havre depuis 2010, il a été Premier ministre de mai 2017 à juillet 2020, avant de fonder le parti Horizons en 2021, qu''il préside.', 'https://www.edouardphilippe.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 6) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), 'xavier-bertrand', 'Xavier Bertrand', '/candidates/xavier-bertrand.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:sans-etiquette-droite'), 'Né le 21 mars 1965 à Châlons-en-Champagne, Xavier Bertrand a été ministre de la Santé (2005-2007) puis du Travail (2007-2012). Président du conseil régional des Hauts-de-France depuis 2016, il a quitté Les Républicains en 2017 et se présente via son mouvement personnel « Nous France ».', null, uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 7) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), 'bruno-retailleau', 'Bruno Retailleau', '/candidates/bruno-retailleau.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:lr'), 'Né en 1960 à Cholet, Bruno Retailleau est sénateur de la Vendée depuis 2004 et a présidé le conseil régional des Pays de la Loire (2016-2017). Ministre de l''Intérieur de septembre 2024 à octobre 2025, il préside le parti Les Républicains depuis mai 2025.', 'https://republicains.fr', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 8) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), 'marine-le-pen', 'Marine Le Pen', '/candidates/marine-le-pen.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:rn'), 'Née le 5 août 1968 à Neuilly-sur-Seine, Marine Le Pen est avocate de formation. Présidente du Front National puis du Rassemblement National de 2011 à 2021, elle est députée du Pas-de-Calais et préside le groupe RN à l''Assemblée nationale depuis 2022. Elle a été candidate à la présidentielle en 2012, 2017 et 2022. En juillet 2026, la cour d''appel de Paris l''a condamnée dans l''affaire des assistants parlementaires du RN à une peine d''inéligibilité déjà exécutée et à une peine de prison aménagée, sans l''empêcher de se présenter en 2027 ; elle s''est pourvue en cassation.', 'https://rassemblementnational.fr/membre/marine-le-pen', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 9) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), 'david-lisnard', 'David Lisnard', '/candidates/david-lisnard.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:nouvelle-energie'), 'Né le 2 février 1969 à Limoges, David Lisnard est diplômé de l''Institut d''études politiques de Bordeaux. Maire de Cannes depuis 2014 et président de l''Association des maires de France depuis 2021, il a quitté Les Républicains le 31 mars 2026 pour se présenter à la présidentielle de 2027 via le mouvement Nouvelle Énergie, qu''il préside.', 'https://www.unenouvelleenergie.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 10) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), 'fabien-roussel', 'Fabien Roussel', '/candidates/fabien-roussel.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:pcf'), 'Né le 16 avril 1969 à Béthune, Fabien Roussel a d''abord été journaliste avant de devenir secrétaire national du Parti communiste français depuis novembre 2018. Ancien député du Nord (2017-2024), il est maire de Saint-Amand-les-Eaux depuis janvier 2025. Candidat à la présidentielle en 2022 (2,28 %, 8e place), il se représente en 2027.', 'http://www.fabienroussel2027.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 11) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), 'nathalie-arthaud', 'Nathalie Arthaud', '/candidates/nathalie-arthaud.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:lo'), 'Née le 23 février 1970 à Peyrins (Drôme), Nathalie Arthaud est professeure agrégée d''économie-gestion. Porte-parole de Lutte Ouvrière depuis décembre 2008, elle a succédé à Arlette Laguiller comme visage du parti. Candidate à la présidentielle en 2012, 2017 et 2022 (autour de 0,6 % à chaque fois), elle se présente pour la quatrième fois en 2027.', 'https://www.lutte-ouvriere.org/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 12) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), 'nicolas-dupont-aignan', 'Nicolas Dupont-Aignan', '/candidates/nicolas-dupont-aignan.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:dlf'), 'Né le 7 mars 1961 à Paris, Nicolas Dupont-Aignan est diplômé de Sciences Po Paris et de l''ENA. Ancien membre du RPR puis de l''UMP, il fonde Debout la France en 2008, qu''il préside depuis. Maire de Yerres (1995-2017, puis à nouveau depuis 2020) et ancien député de l''Essonne (1997-2024), il a été candidat à la présidentielle en 2012, 2017 (4,7 %) et 2022, et se présente pour la cinquième fois en 2027.', 'https://www.debout-la-france.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 13) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Faut-il repousser l''âge légal de départ à la retraite au-delà de 64 ans ?', 'Pour équilibrer le financement du système par répartition.', 'L''âge légal de départ à la retraite détermine l''âge minimum à partir duquel une personne peut demander sa retraite, sous réserve des autres conditions applicables (durée de cotisation notamment).', 1.5, 'likert', '[{"id":"favorable-fort","label":"Tout à fait favorable","value":2},{"id":"favorable","label":"Plutôt favorable","value":1},{"id":"neutre","label":"Neutre","value":0},{"id":"oppose","label":"Plutôt opposé","value":-1},{"id":"oppose-fort","label":"Totalement opposé","value":-2}]'::jsonb, null, 1, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Les personnes ayant eu une carrière longue ou un métier pénible devraient-elles pouvoir partir à la retraite avant l''âge légal ?', null, 'Certains dispositifs permettent un départ anticipé pour les carrières commencées tôt ou pour les métiers reconnus comme pénibles, indépendamment de l''âge légal général.', 1, 'likert', '[{"id":"favorable-fort","label":"Tout à fait favorable","value":2},{"id":"favorable","label":"Plutôt favorable","value":1},{"id":"neutre","label":"Neutre","value":0},{"id":"oppose","label":"Plutôt opposé","value":-1},{"id":"oppose-fort","label":"Totalement opposé","value":-2}]'::jsonb, null, 2, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Pour redresser les finances publiques, quelle approche vous semble la plus prioritaire ?', 'Choisissez la position la plus proche de la vôtre.', 'Le déficit public correspond à l''écart entre les dépenses et les recettes de l''État sur une année ; la dette publique est l''accumulation de ces déficits dans le temps.', 1, 'choice', '[{"id":"reduire-depenses","label":"Réduire les dépenses publiques"},{"id":"augmenter-impots","label":"Augmenter les impôts, en particulier pour les plus favorisés"},{"id":"relancer-croissance","label":"Relancer la croissance pour augmenter les recettes, sans changer les taux"},{"id":"pas-prioritaire","label":"Ne pas en faire une priorité immédiate"}]'::jsonb, null, 3, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q5'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Pour améliorer le pouvoir d''achat, quelle politique devrait être prioritaire selon vous ?', 'Choisissez la position la plus proche de la vôtre.', 'Le pouvoir d''achat dépend à la fois du niveau des salaires, du niveau des prix, des prélèvements obligatoires et des aides sociales — plusieurs leviers distincts permettent d''agir dessus.', 1, 'choice', '[{"id":"augmenter-salaires","label":"Augmenter les salaires"},{"id":"reduire-taxes","label":"Réduire les taxes et prélèvements sur le travail"},{"id":"encadrer-prix","label":"Bloquer ou encadrer certains prix"},{"id":"renforcer-aides","label":"Renforcer les aides ciblées aux ménages modestes"}]'::jsonb, null, 4, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q6'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Quel niveau d''immigration légale la France devrait-elle viser ?', null, 'L''immigration légale recouvre plusieurs canaux distincts (travail, famille, études, asile) encadrés par la loi, par opposition à l''entrée ou au séjour irréguliers.', 1.5, 'likert', '[{"id":"fortement-moins","label":"Fortement réduire","value":-2},{"id":"moins","label":"Réduire","value":-1},{"id":"maintenir","label":"Maintenir","value":0},{"id":"plus","label":"Augmenter","value":1},{"id":"fortement-plus","label":"Fortement augmenter","value":2}]'::jsonb, null, 5, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q7'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Faut-il faciliter la régularisation des travailleurs sans papiers dans les métiers en tension ?', null, 'Un métier « en tension » est un métier pour lequel les employeurs peinent à recruter, faute de candidats suffisants sur le marché du travail.', 1, 'likert', '[{"id":"favorable-fort","label":"Tout à fait favorable","value":2},{"id":"favorable","label":"Plutôt favorable","value":1},{"id":"neutre","label":"Neutre","value":0},{"id":"oppose","label":"Plutôt opposé","value":-1},{"id":"oppose-fort","label":"Totalement opposé","value":-2}]'::jsonb, null, 6, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q9'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:securite'), 'Quelle doit être la priorité en matière de justice pénale ?', 'Choisissez la position la plus proche de la vôtre.', 'La justice pénale peut privilégier la sanction (peines plus sévères, plus rapides) ou la prévention (traitement des causes de la délinquance, réinsertion) — la plupart des politiques combinent les deux à des degrés différents.', 1, 'likert', '[{"id":"sanction-fort","label":"Sanctionner plus sévèrement et plus vite","value":2},{"id":"sanction","label":"Plutôt renforcer la sanction","value":1},{"id":"equilibre","label":"Un équilibre entre sanction et prévention","value":0},{"id":"prevention","label":"Plutôt renforcer la prévention","value":-1},{"id":"prevention-fort","label":"Développer les peines alternatives et la prévention","value":-2}]'::jsonb, null, 7, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q10'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:sante'), 'Comment devrait évoluer le budget de l''hôpital public et les effectifs de soignants ?', null, 'Le budget de l''hôpital public conditionne notamment le nombre de lits ouverts et les effectifs de soignants (médecins, infirmiers, aides-soignants) en poste.', 1, 'likert', '[{"id":"fortement-moins","label":"Fortement diminuer","value":-2},{"id":"moins","label":"Diminuer","value":-1},{"id":"maintenir","label":"Maintenir au niveau actuel","value":0},{"id":"plus","label":"Augmenter","value":1},{"id":"fortement-plus","label":"Fortement augmenter","value":2}]'::jsonb, null, 8, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q11'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:sante'), 'Pour réduire les délais d''attente et améliorer l''accès aux soins, quelle approche vous semble la plus prioritaire ?', 'Choisissez la position la plus proche de la vôtre.', 'L''accès aux soins peut se heurter à des délais d''attente, à des « déserts médicaux » dans certains territoires, ou aux capacités d''accueil des établissements publics et privés.', 1, 'choice', '[{"id":"renforcer-public","label":"Renforcer et recruter davantage dans l''hôpital public"},{"id":"developper-prive","label":"Développer davantage l''offre de soins privée"},{"id":"repartition-territoriale","label":"Mieux répartir l''offre de soins sur le territoire"},{"id":"prevention-telemedecine","label":"Développer la prévention et la télémédecine"}]'::jsonb, null, 9, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q12'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Faut-il donner plus d''autonomie pédagogique et budgétaire aux établissements scolaires ?', null, 'L''autonomie des établissements scolaires porte sur leur capacité à adapter leurs méthodes pédagogiques et à gérer une partie de leur budget, par rapport à un cadre national uniforme.', 1, 'likert', '[{"id":"favorable-fort","label":"Tout à fait favorable","value":2},{"id":"favorable","label":"Plutôt favorable","value":1},{"id":"neutre","label":"Neutre","value":0},{"id":"oppose","label":"Plutôt opposé","value":-1},{"id":"oppose-fort","label":"Totalement opposé","value":-2}]'::jsonb, null, 10, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q13'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Comment devrait évoluer la rémunération des enseignants ?', null, 'Le salaire des enseignants en France se compare à celui d''autres pays européens et à celui d''autres professions à niveau de qualification équivalent.', 1, 'likert', '[{"id":"fortement-moins","label":"Fortement diminuer","value":-2},{"id":"moins","label":"Diminuer","value":-1},{"id":"maintenir","label":"Rester stable","value":0},{"id":"plus","label":"Augmenter","value":1},{"id":"fortement-plus","label":"Fortement augmenter","value":2}]'::jsonb, null, 11, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q14'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:ecologie'), 'Les normes environnementales imposées aux entreprises devraient-elles être renforcées, maintenues ou allégées ?', null, 'Les normes environnementales imposées aux entreprises (émissions, usage de produits, obligations de reporting…) ont un coût de mise en conformité, mais visent à limiter leur impact écologique.', 1.5, 'likert', '[{"id":"fortement-moins","label":"Fortement allégées","value":-2},{"id":"moins","label":"Allégées","value":-1},{"id":"maintenir","label":"Maintenues au niveau actuel","value":0},{"id":"plus","label":"Renforcées","value":1},{"id":"fortement-plus","label":"Fortement renforcées","value":2}]'::jsonb, null, 12, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q15'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Concernant la production d''électricité, quelle priorité vous paraît la plus importante ?', 'Choisissez la position la plus proche de la vôtre.', 'Le mix énergétique français combine aujourd''hui principalement le nucléaire et les énergies renouvelables (hydraulique, éolien, solaire) pour produire de l''électricité.', 1, 'choice', '[{"id":"nucleaire","label":"Développer principalement le nucléaire"},{"id":"renouvelables","label":"Développer principalement les renouvelables"},{"id":"sobriete","label":"Réduire prioritairement la consommation"},{"id":"mix","label":"Conserver un mix énergétique diversifié"}]'::jsonb, null, 13, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q16'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:europe'), 'Quel niveau d''intégration européenne (transfert de compétences nationales à l''Union européenne) vous semble souhaitable ?', null, 'L''Union européenne exerce aujourd''hui des compétences dans des domaines variés (commerce, concurrence, une partie de l''agriculture…), à des degrés différents selon les sujets.', 1, 'likert', '[{"id":"fortement-moins","label":"Fortement réduire l''intégration (rapatrier des compétences)","value":-2},{"id":"moins","label":"Réduire l''intégration","value":-1},{"id":"maintenir","label":"Statu quo","value":0},{"id":"plus","label":"Renforcer l''intégration","value":1},{"id":"fortement-plus","label":"Fortement renforcer l''intégration","value":2}]'::jsonb, null, 14, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q17'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:international'), 'La France devrait-elle renforcer son autonomie stratégique et militaire vis-à-vis de ses alliances actuelles (dont l''OTAN), ou continuer de s''appuyer sur elles ?', null, 'L''OTAN est une alliance militaire entre pays nord-américains et européens ; l''autonomie stratégique désigne la capacité d''un pays à agir militairement sans dépendre de ses alliés.', 1, 'likert', '[{"id":"fortement-moins","label":"Fortement vers plus d''intégration dans les alliances actuelles","value":-2},{"id":"moins","label":"Plutôt vers plus d''intégration","value":-1},{"id":"maintenir","label":"Statu quo","value":0},{"id":"plus","label":"Plutôt vers plus d''autonomie","value":1},{"id":"fortement-plus","label":"Fortement vers plus d''autonomie stratégique","value":2}]'::jsonb, null, 15, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q18'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:logement'), 'L''encadrement des loyers dans les zones tendues devrait-il être renforcé, maintenu, ou levé ?', null, 'Une « zone tendue » est un secteur où la demande de logements dépasse fortement l''offre disponible ; l''encadrement des loyers y plafonne les loyers pratiqués à la relocation.', 1, 'likert', '[{"id":"fortement-moins","label":"Totalement levé","value":-2},{"id":"moins","label":"Plutôt allégé","value":-1},{"id":"maintenir","label":"Maintenu au niveau actuel","value":0},{"id":"plus","label":"Plutôt renforcé","value":1},{"id":"fortement-plus","label":"Fortement renforcé, étendu à tout le territoire","value":2}]'::jsonb, null, 16, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q19'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Parmi ces grands sujets, lequel est pour vous le plus prioritaire pour le prochain quinquennat ?', 'Ce choix ne vous compare à aucun candidat.', 'Vos réponses sur ce sujet compteront un peu plus dans le calcul de votre proximité avec chaque candidat — cela ne change jamais les positions des candidats eux-mêmes, ni la façon dont elles sont notées.', 1, 'priority', '[{"id":"economie","label":"Économie","theme_id":"theme-economie"},{"id":"pouvoir-achat","label":"Pouvoir d''achat","theme_id":"theme-pouvoir-achat"},{"id":"retraites","label":"Retraites","theme_id":"theme-retraites"},{"id":"immigration","label":"Immigration","theme_id":"theme-immigration"},{"id":"securite","label":"Sécurité","theme_id":"theme-securite"},{"id":"sante","label":"Santé","theme_id":"theme-sante"},{"id":"education","label":"Éducation","theme_id":"theme-education"},{"id":"ecologie","label":"Écologie","theme_id":"theme-ecologie"},{"id":"energie","label":"Énergie","theme_id":"theme-energie"},{"id":"europe","label":"Europe","theme_id":"theme-europe"},{"id":"international","label":"International","theme_id":"theme-international"},{"id":"logement","label":"Logement","theme_id":"theme-logement"}]'::jsonb, null, 17, true) on conflict (id) do nothing;
insert into questions (id, theme_id, question, description, context, weight, answer_type, options, compatibility, order_index, is_active) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q20'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Et en second choix, quel autre sujet compte aussi beaucoup pour vous ?', 'Optionnel — ce choix ne vous compare à aucun candidat.', 'Comme pour la question précédente, ce second choix ajuste seulement la pondération de vos propres résultats, avec un effet un peu plus léger que votre premier choix.', 1, 'priority', '[{"id":"economie","label":"Économie","theme_id":"theme-economie"},{"id":"pouvoir-achat","label":"Pouvoir d''achat","theme_id":"theme-pouvoir-achat"},{"id":"retraites","label":"Retraites","theme_id":"theme-retraites"},{"id":"immigration","label":"Immigration","theme_id":"theme-immigration"},{"id":"securite","label":"Sécurité","theme_id":"theme-securite"},{"id":"sante","label":"Santé","theme_id":"theme-sante"},{"id":"education","label":"Éducation","theme_id":"theme-education"},{"id":"ecologie","label":"Écologie","theme_id":"theme-ecologie"},{"id":"energie","label":"Énergie","theme_id":"theme-energie"},{"id":"europe","label":"Europe","theme_id":"theme-europe"},{"id":"international","label":"International","theme_id":"theme-international"},{"id":"logement","label":"Logement","theme_id":"theme-logement"}]'::jsonb, null, 18, true) on conflict (id) do nothing;
